"use client";

import { forwardRef } from "react";
import {
  Dialog as AriaDialog,
  DialogTrigger,
  Popover as AriaPopover,
  type PopoverProps as AriaPopoverProps,
} from "react-aria-components";
import { popoverDefaults, type PopoverSpecProps } from "../generated/popover.types";
import { Arrow } from "../utils/arrow";
import { cx } from "../utils/cx";

export { DialogTrigger as PopoverTrigger };

export interface PopoverProps
  extends PopoverSpecProps,
    Omit<AriaPopoverProps, keyof PopoverSpecProps | "className" | "children"> {
  className?: string;
}

export const Popover = forwardRef<HTMLElement, PopoverProps>(function Popover(
  {
    label,
    placement = popoverDefaults.placement,
    showArrow = popoverDefaults.showArrow,
    children,
    className,
    ...rest
  },
  ref,
) {
  return (
    <AriaPopover
      {...rest}
      ref={ref}
      placement={placement}
      offset={showArrow ? 12 : 8}
      className={cx(
        "[box-shadow:var(--rd-elevation-floating)] bg-[var(--rd-color-surface-raised)] text-[var(--rd-color-text-default)] " +
          "border border-[var(--rd-color-border-default)] rounded-[var(--rd-radius-overlay)]",
        className,
      )}
    >
      {showArrow && (
        <Arrow className="fill-[var(--rd-color-surface-raised)] stroke-[var(--rd-color-border-default)]" />
      )}
      <AriaDialog aria-label={label} className="p-1.5 outline-none">
        {children}
      </AriaDialog>
    </AriaPopover>
  );
});

// Generated by rdloom codegen from specs/popover.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

export const popoverPlacementValues = ["top", "bottom", "start", "end"] as const;

/** Non-modal panel anchored to a trigger, for extra controls or details. Open it with DialogTrigger. */
export interface PopoverSpecProps {
  /**
   * Accessible name for the popover content.
   */
  label: string;
  /**
   * Preferred side of the trigger. Flips when there isn't room.
   * @default "bottom"
   */
  placement?: "top" | "bottom" | "start" | "end";
  /**
   * Shows an arrow pointing at the trigger.
   * @default false
   */
  showArrow?: boolean;
  /**
   * Popover content. A function receives close().
   */
  children?: ReactNode | ((opts: { close: () => void }) => ReactNode);
}

export const popoverDefaults = {
  placement: "bottom",
  showArrow: false,
} as const;

export const popoverMeta = {
  "name": "Popover",
  "version": "0.1.0",
  "status": "experimental",
  "role": "dialog"
} as const;
